"""Train the three-feature quantum classifier and all four classical baselines."""

from dataclasses import dataclass
from pathlib import Path

import numpy as np

import flagquantum as fq
from examples.synthesis.algorithms.machine_learning.qsvm.overview.datasets import (
    Dataset,
    Split,
)
from examples.synthesis.algorithms.machine_learning.qsvm.overview.workflow import (
    SHOTS,
    Score,
    StateArray,
    sample_kernel,
)
from examples.synthesis.applications.finance.credit_card_fraud.comparisons.circuit import (
    reference_circuit,
)

from . import model, quantum

SAMPLE_SEED = 1297


@dataclass(frozen=True)
class Run:
    data: model.Data
    score: Score
    classical: tuple[tuple[str, float], ...]
    verification: tuple[float, ...]


def feature_states(dataset: Dataset) -> StateArray:
    return np.asarray(
        [
            quantum.state(tuple(map(float, row))).detach().cpu().numpy()
            for row in dataset.points
        ],
        dtype=np.complex128,
    )


def classify(split: Split) -> Score:
    from sklearn.svm import SVC

    rng = np.random.default_rng(SAMPLE_SEED)
    train = feature_states(split.train)
    matrix, pairs = sample_kernel(train, None, rng)
    classifier = SVC(kernel="precomputed").fit(matrix, split.train.labels)
    support = train[classifier.support_]
    labels = []
    for group in (split.test, split.predict):
        kernel, visits = sample_kernel(feature_states(group), support, rng)
        decision = kernel @ classifier.dual_coef_[0] + classifier.intercept_[0]
        labels.append(
            np.asarray(
                np.where(decision >= 0, classifier.classes_[1], classifier.classes_[0]),
                dtype=np.int64,
            )
        )
        pairs += visits
    test, predict = labels
    return Score(
        float(np.mean(test == split.test.labels)),
        float(np.mean(predict == split.predict.labels)),
        test,
        predict,
        len(support),
        pairs,
    )


def classical(split: Split) -> tuple[tuple[str, float], ...]:
    from sklearn.svm import SVC

    return tuple(
        (
            kernel,
            float(
                SVC(kernel=kernel)
                .fit(split.train.points, split.train.labels)
                .score(split.test.points, split.test.labels)
            ),
        )
        for kernel in model.CLASSICAL_KERNELS
    )


def compare(split: Split) -> tuple[float, ...]:
    """Check both complete overlap states for distinct newly transformed points."""
    errors = []
    for first, second in ((0, 3), (104, 115)):
        left = tuple(map(float, split.train.points[first]))
        right = tuple(map(float, split.train.points[second]))
        program = quantum.overlap(left, right)
        actual = fq.run(program).statevector().flatten()
        expected = fq.run(reference_circuit(left, right)).statevector().flatten()
        error = float((actual - expected).abs().max())
        if error >= 1e-12 or program.report["workspace_qubits"] != 0:
            raise AssertionError(f"Overlap full-state error {error}")
        if (
            abs(
                float(actual[0].abs().square())
                - float(quantum.state(left).vdot(quantum.state(right)).abs().square())
            )
            >= 1e-12
        ):
            raise AssertionError(
                "Batched feature overlap disagrees with the executed kernel"
            )
        errors.append(error)
    return tuple(errors)


def run(path: Path = model.DATA) -> Run:
    data = model.prepare(path)
    return Run(
        data, classify(data.features), classical(data.features), compare(data.features)
    )


def trial_count(result: Run) -> int:
    return result.score.sampled_pairs * SHOTS

"""Reuse the original three-feature Pauli embedding for all selected rows."""

import math
from typing import Annotated

import torch

import flagquantum as fq
from examples.synthesis.applications.finance.credit_card_fraud.main import (
    main as overlap_root,
)
from examples.synthesis.applications.finance.credit_card_fraud.main import (
    pauli_kernel,
)
from flagquantum import synth
from flagquantum.synth import Output, QNum, allocate, qfunc


@qfunc
def encode(data: list[float], q: Output[Annotated[QNum, 3]]) -> None:
    allocate(q)
    pauli_kernel(data, q)


def checked(values: tuple[float, ...]) -> tuple[float, ...]:
    if len(values) != 3 or not all(math.isfinite(value) for value in values):
        raise ValueError("Three finite PCA coordinates are required")
    return values


def overlap(left: tuple[float, ...], right: tuple[float, ...]) -> synth.Program:
    return synth.synthesize(
        overlap_root,
        classical_inputs={"data1": checked(left), "data2": checked(right)},
        max_qubits=3,
        max_workspace=0,
        max_operations=96,
        memory_limit_bytes=1024**2,
    )


def state(data: tuple[float, ...]) -> torch.Tensor:
    program = synth.synthesize(
        encode,
        classical_inputs={"data": checked(data)},
        max_qubits=3,
        max_workspace=0,
        max_operations=64,
        memory_limit_bytes=1024**2,
    )
    vector: torch.Tensor = fq.run(program).statevector().flatten()
    return vector

"""Use every archived transaction and preserve the original deterministic splits."""

import csv
import hashlib
import math
from dataclasses import dataclass
from pathlib import Path

import numpy as np
from numpy.typing import NDArray

from examples.synthesis.algorithms.machine_learning.qsvm.overview.datasets import (
    Dataset,
    Split,
)

DATA = Path("creditcard.csv")
SOURCE_DIGEST = "cb6baeefbfd24b7b8f865b55efa366e2023b35bb125bc88a9f08a4c03724e5cd"
FEATURES = 29
SPLIT_COUNTS = ((100, 25), (50, 10), (50, 10))
LABELS = ("Nominal", "Fraud")
CLASSICAL_KERNELS = ("linear", "poly", "rbf", "sigmoid")
SEED_TSNE = 20150101


@dataclass(frozen=True)
class Data:
    rows: int
    by_class: tuple[int, int]
    raw: Split
    features: Split


def read(path: Path = DATA) -> tuple[NDArray[np.float64], NDArray[np.float64]]:
    buckets: tuple[list[list[float]], list[list[float]]] = ([], [])
    with path.open(newline="") as stream:
        reader = csv.DictReader(stream)
        columns = reader.fieldnames
        if columns is None or columns[0] != "Time" or columns[-1] != "Class":
            raise ValueError("The source asset must contain Time, features and Class")
        fields = columns[1:-1]
        if len(fields) != FEATURES:
            raise ValueError(
                f"The source asset must contain {FEATURES} feature columns"
            )
        for row in reader:
            label = int(row["Class"])
            if label not in (0, 1):
                raise ValueError("Source labels must be binary")
            point = [float(row[name]) for name in fields]
            if not all(math.isfinite(value) for value in point):
                raise ValueError("The source transaction features must be finite")
            buckets[label].append(point)
    return np.asarray(buckets[0], dtype=np.float64), np.asarray(
        buckets[1], dtype=np.float64
    )


def partition(classes: tuple[NDArray[np.float64], NDArray[np.float64]]) -> Split:
    if len(classes[0]) < 200 or len(classes[1]) < 45:
        raise ValueError(
            "The source split requires at least 200 nominal and 45 fraud rows"
        )
    groups = []
    first, second = 0, 0
    for n0, n1 in SPLIT_COUNTS:
        selected = np.concatenate(
            (classes[0][first : first + n0], classes[1][second : second + n1])
        )
        labels = np.repeat(np.arange(2, dtype=np.int64), (n0, n1))
        groups.append(Dataset(selected, labels))
        first, second = first + n0, second + n1
    return Split(*groups)


def transform(split: Split) -> Split:
    from sklearn.decomposition import PCA
    from sklearn.preprocessing import MinMaxScaler, StandardScaler

    source = (split.train, split.test, split.predict)
    pca = PCA(n_components=3).fit(split.train.points)
    reduced = [pca.transform(group.points) for group in source]
    standard = StandardScaler().fit(reduced[0])
    standardized = [standard.transform(points) for points in reduced]
    scaler = MinMaxScaler((-math.pi, math.pi)).fit(np.concatenate(standardized))
    return Split(
        *(
            Dataset(
                np.asarray(scaler.transform(points), dtype=np.float64), group.labels
            )
            for points, group in zip(standardized, source, strict=True)
        )
    )


def prepare(path: Path = DATA) -> Data:
    if hashlib.sha256(path.read_bytes()).hexdigest() != SOURCE_DIGEST:
        raise ValueError(
            "Use the pinned 948-row source CSV listed in the example README"
        )
    classes = read(path)
    raw = partition(classes)
    totals = (len(classes[0]), len(classes[1]))
    return Data(sum(totals), totals, raw, transform(raw))


def embed(group: Dataset) -> NDArray[np.float64]:
    """Apply the source's original t-SNE declaration to one raw split."""
    from sklearn.manifold import TSNE

    return np.asarray(
        TSNE(random_state=SEED_TSNE).fit_transform(group.points), dtype=np.float64
    )

"""Independent gate-level feature overlap in reversed inverse-layer order."""

import math

import torch

import flagquantum as fq
from examples.synthesis.applications.finance.credit_card_fraud.main import (
    DATA_PAIRS,
    build_program,
)
from examples.synthesis.compare_states import compare_states

DTYPE = torch.complex128


def reference_circuit(data1: tuple[float, ...], data2: tuple[float, ...]) -> fq.Circuit:
    circuit = fq.Circuit(3, dtype=DTYPE)
    pairs = ((0, 1), (0, 2), (1, 2))
    for _ in range(2):
        for bit in range(3):
            circuit.h(2 - bit)
        for bit, value in enumerate(data1):
            circuit.rz(2 - bit, theta=2 * value)
        for first, second in pairs:
            circuit.rzz(
                2 - first,
                2 - second,
                theta=2 * (data1[first] - math.pi) * (data1[second] - math.pi),
            )
    # The adjoint reverses each E H layer, not only its rotation signs.
    for _ in range(2):
        for first, second in reversed(pairs):
            circuit.rzz(
                2 - first,
                2 - second,
                theta=-2 * (data2[first] - math.pi) * (data2[second] - math.pi),
            )
        for bit in reversed(range(3)):
            circuit.rz(2 - bit, theta=-2 * data2[bit])
        for bit in reversed(range(3)):
            circuit.h(2 - bit)
    return circuit


def run_example() -> None:
    for data1, data2 in DATA_PAIRS:
        compare_states(
            build_program(data1, data2), reference_circuit(data1, data2), ("qba",)
        )


if __name__ == "__main__":
    run_example()

